size(39, 4, 16, 1.25);
name("flintlock pistol");

// Lies on its left side, lock uppermost.
// x: butt (0) to muzzle (38). z: under the butt (0) up to the cock (15). y: thickness.

function rep(c, n) { var s = ""; for (var i = 0; i < n; i++) s += c; return s; }

// walnut: grain runs along the barrel in front and down the grip behind
var GRAIN = ["2:6", "1:6", "2:6", "2:9"];
function walnut(x, z, edge) {
  var i = (x < 9 && z < 9) ? x - z + 8 : z + ((x + 2 * z) >> 2);
  var c = GRAIN[i & 3], r = rng();
  if (edge) { if (r < 0.5) c = "2:9"; }
  else if (x < 9 && z < 8) { if (r < 0.22) c = "2:5"; }
  else if (r < 0.12) c = GRAIN[(i + 1) & 3];
  return c;
}

function cell(c, x, y, z) {
  var r = rng(), k;
  if (c === "W" || c === "w") { put("wood", walnut(x, z, c === "w"), x, y, z); return; }
  if (c === "r") { put("wood", r < 0.6 ? "own" : "3:7", x, y, z); return; }   // ramrod
  if (c === "f") { put("rock", "grey:12", x, y, z); return; }                  // flint
  if (c === "S") k = r < 0.55 ? "grey:5" : r < 0.8 ? "grey:4" : "grey:6";      // barrel
  else if (c === "s") k = r < 0.6 ? "grey:6" : r < 0.85 ? "grey:7" : "grey:5"; // barrel, turning away
  else if (c === "P") k = r < 0.6 ? "grey:7" : "grey:6";                       // lock plate
  else if (c === "C") k = r < 0.6 ? "grey:9" : "grey:8";                       // cock
  else if (c === "F") k = r < 0.6 ? "grey:4" : "grey:5";                       // frizzen
  else if (c === "B") k = r < 0.62 ? "3:3" : "3:8";                            // brass
  else if (c === "b") k = r < 0.55 ? "3:8" : "3:9";                            // brass in shade
  else if (c === "h") k = "3:2";                                               // brass, polished
  else if (c === "o") k = "grey:3";                                            // bright screw head
  else if (c === "t") k = "grey:7";                                            // tang
  else if (c === "x") k = "grey:10";                                           // screw slot
  else if (c === "n") k = "grey:11";                                           // pan
  else if (c === "k") k = "black";                                             // bore
  else if (c === "G" || c === "T") k = "grey:9";                               // spring, trigger
  else k = "grey:8";                                                           // jaws, fence, powder burn
  put("steel", k, x, y, z);
}

function row(y, z, x0, s) {
  for (var i = 0; i < s.length; i++) {
    var c = s.charAt(i);
    if (c !== ".") cell(c, x0 + i, y, z);
  }
}

// ---- y = 1 : the middle plane, the whole outline ----
row(1, 13, 36, "h");                                             // front sight
row(1, 12, 12, "txtdsd" + rep("s", 21));                         // tang, top of barrel
row(1, 11, 10, "wwWWW" + rep("S", 22) + "k");                    // barrel core, open bore at the muzzle
row(1, 10, 8, "w" + rep("W", 6) + rep("s", 24));                 // underside of barrel
row(1, 9, 7, "w" + rep("W", 12) + "BB" + rep("r", 6) + "BB" + rep("r", 6) + "B"); // pipes and ramrod
row(1, 8, 7, "w" + rep("W", 8) + "BBW");                         // belly, guard finial
row(1, 7, 6, "wWWw..T..B");                                      // trigger, guard post
row(1, 6, 5, "wWWw.....BB");
row(1, 5, 4, "wWWb" + rep("B", 7));                              // guard bow
row(1, 4, 3, "wWWb");
row(1, 3, 1, "bBWWw");
row(1, 2, 0, "bBBBw");
row(1, 1, 0, "bBBb");
row(1, 0, 1, "bbb");

// ---- y = 0 and y = 2 : the two cheeks ----
function side(y, lockSide) {
  row(y, 11, 12, "WWW" + rep("S", 24));
  if (lockSide) {
    row(y, 10, 9, "WWW" + rep("P", 8) + rep("W", 15) + "B");
    row(y, 9, 8, "WW" + "Px" + rep("P", 7) + "W" + "BB......BB");
  } else {
    row(y, 10, 9, "WWWW" + "BBBoB" + "WW" + rep("W", 15) + "B"); // brass side plate, lock screws
    row(y, 9, 8, "WWW" + "BoBBB" + "WWWW" + "BB......BB");
  }
  row(y, 8, 8, rep("W", 11));
  row(y, 7, 7, "WW");
  row(y, 6, 6, "WW");
  row(y, 5, 5, "WW");
  row(y, 4, 4, "BW");                                            // butt cap spur
  row(y, 3, 2, "BBW");
  row(y, 2, 1, "BBB");
  row(y, 1, 1, "BB");
}
side(0, false);
side(2, true);

