row(3, 13, 12, "JJf.F");      // lower jaw, flint
row(3, 12, 12, "C...F");      // neck
row(3, 11, 12, "C..enG");     // fence, pan, frizzen toe
row(3, 10, 12, "Co...GG");    // cock boss and screw, frizzen spring
